{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE `maplemonk.shopify_vs_unicommerce_live_skus` AS WITH Unicommerce_Inventory_Base AS ( SELECT * FROM ( SELECT DATETIME(TIMESTAMP(timestamp), \"Asia/Kolkata\") AS DATA_FETCH_DATE, REPLACE(SKUCODE, \'\\'\', \'\') AS SKU, FACILITY AS LOCATION_KEY, INVENTORY AS AVAILABLEINVENTORY, pendingInventoryAssessment AS PENDINGASSESSMENT, ROW_NUMBER() OVER ( PARTITION BY FACILITY, REPLACE(SKUCODE, \'\\'\', \'\'), CAST(DATETIME(TIMESTAMP(timestamp), \"Asia/Kolkata\") AS DATE) ORDER BY DATETIME(TIMESTAMP(timestamp), \"Asia/Kolkata\") DESC ) AS rw FROM `MAPLEMONK.UNICOMMERCE_ZOUK_UC_GET_INVENTORY_SNAPSHOT` ) WHERE rw = 1 AND LOWER(LOCATION_KEY) LIKE ANY (\'zoukst\',\'doto\',\'zoukst_bantalla\',\'everpret\',\'1991\',\'repairsunit\') AND DATE(DATA_FETCH_DATE) <= \'2026-08-02\' UNION ALL SELECT * FROM ( SELECT DATETIME(DATE(_airbyte_emitted_at, \"Asia/Kolkata\")) AS DATA_FETCH_DATE, REPLACE(Item_SkuCode, \'\\'\', \'\') AS SKU, FACILITY AS LOCATION_KEY, CAST(INVENTORY AS INT64) AS AVAILABLEINVENTORY, CAST(pending_Inventory_Assessment AS INT64) AS PENDINGASSESSMENT, ROW_NUMBER() OVER ( PARTITION BY FACILITY, REPLACE(Item_SkuCode, \'\\'\', \'\'), CAST(DATETIME(TIMESTAMP(_airbyte_emitted_at), \"Asia/Kolkata\") AS DATE) ORDER BY DATETIME(TIMESTAMP(_airbyte_emitted_at), \"Asia/Kolkata\") DESC ) AS rw FROM `MapleMonk.stlp_uc_get_inventory_snapshot_export_full_refresh` ) WHERE rw = 1 AND LOWER(LOCATION_KEY) LIKE ANY (\'%sea turtle%\',\'%zoukst%\',\'1991\',\'repairunit\',\'everpret\') AND DATE(DATA_FETCH_DATE) >= \'2026-08-03\' ), Unicommerce_Clean_Data AS ( SELECT CAST(U.DATA_FETCH_DATE AS DATE) AS DATA_FETCH_DATE, U.SKU, COALESCE(SM.CATEGORY, \'Unmapped\') AS CATEGORY, CASE WHEN MAX(IFNULL(U.AVAILABLEINVENTORY, 0) - IFNULL(U.PENDINGASSESSMENT, 0)) > 1 THEN 1 ELSE 0 END AS uc_availability_flag, SUM(IFNULL(U.AVAILABLEINVENTORY, 0)) AS uc_available_inventory FROM Unicommerce_Inventory_Base U LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY commonsku ORDER BY 1) AS rw FROM `MAPLEMONK.FINAL_SKU_MASTER` ) WHERE rw = 1 ) SM ON LOWER(U.SKU) = LOWER(SM.commonsku) WHERE LOWER(U.SKU) NOT LIKE \'%zip-%\' AND LOWER(IFNULL(SM.TYPE, \'\')) NOT LIKE \'%bundle%\' AND LOWER(IFNULL(SM.CATEGORY, \'\')) NOT LIKE \'%shopping bag%\' GROUP BY 1, 2, 3 ), Shopify_Inventory AS ( SELECT CAST(DATETIME(TIMESTAMP(_airbyte_normalized_at), \"Asia/Kolkata\") AS DATE) AS DATA_FETCH_DATE, A.inventory_item_id, MAX(CASE WHEN LOWER(JSON_EXTRACT_SCALAR(B, \'$.name\')) = \'available\' THEN CAST(JSON_EXTRACT_SCALAR(B, \'$.quantity\') AS INT64) END) AS available, MAX(CASE WHEN LOWER(JSON_EXTRACT_SCALAR(B, \'$.name\')) = \'on_hand\' THEN CAST(JSON_EXTRACT_SCALAR(B, \'$.quantity\') AS INT64) END) AS on_hand FROM ( SELECT * FROM `maplemonk.shopify_inventory_levels` WHERE location_id = 19196811 QUALIFY ROW_NUMBER() OVER( PARTITION BY location_id, inventory_item_id, CAST(DATETIME(TIMESTAMP(_airbyte_normalized_at), \"Asia/Kolkata\") AS DATE) ORDER BY DATETIME(TIMESTAMP(_airbyte_normalized_at), \"Asia/Kolkata\") DESC ) = 1 ) A LEFT JOIN UNNEST(A.quantities) B GROUP BY 1, 2 ), Shopify_SKU_Mapping AS ( WITH inventory_item_id AS ( SELECT DISTINCT JSON_EXTRACT_SCALAR(B, \'$.sku\') AS sku, REPLACE(JSON_EXTRACT_SCALAR(B, \'$.inventoryItem.id\'), \'gid://shopify/InventoryItem/\', \'\') AS inventory_item_id FROM `MapleMonk.zouk_db_new_products_graph_ql` LEFT JOIN UNNEST(variants) B WHERE JSON_EXTRACT_SCALAR(B, \'$.sku\') IS NOT NULL ) SELECT fi.sku, fi.inventory_item_id AS inventory_item_id_map, p.category, p.sub_category, p.category_code FROM inventory_item_id fi LEFT JOIN ( SELECT * FROM ( SELECT marketplace_sku AS skucode, category, sub_category, category_code, ROW_NUMBER() OVER (PARTITION BY LOWER(marketplace_sku) ORDER BY 1) AS rw FROM `zouk-wh.maplemonk.final_sku_master` ) WHERE rw = 1 ) p ON LOWER(REPLACE(fi.sku, \' \', \'\')) = LOWER(p.skucode) QUALIFY ROW_NUMBER() OVER(PARTITION BY inventory_item_id_map ORDER BY IFNULL(sku, \'\') DESC) = 1 ), Shopify_SKU_Level AS ( SELECT S.DATA_FETCH_DATE, M.sku, M.category, M.sub_category, S.available AS shopify_available, S.on_hand AS shopify_on_hand FROM Shopify_Inventory S INNER JOIN Shopify_SKU_Mapping M ON LOWER(CAST(S.inventory_item_id AS STRING)) = LOWER(CAST(M.inventory_item_id_map AS STRING)) ), SKU_Comparison AS ( SELECT COALESCE(U.DATA_FETCH_DATE, S.DATA_FETCH_DATE) AS fetch_date, COALESCE(U.sku, S.sku) AS sku, COALESCE(U.category, S.category, \'Unmapped\') AS category, COALESCE(U.uc_availability_flag, 0) AS uc_availability_flag, COALESCE(U.uc_available_inventory, 0) AS uc_available_inventory, COALESCE(S.shopify_available, 0) AS shopify_available FROM Unicommerce_Clean_Data U FULL OUTER JOIN Shopify_SKU_Level S ON LOWER(REPLACE(U.sku, \' \', \'\')) = LOWER(REPLACE(S.sku, \' \', \'\')) AND U.DATA_FETCH_DATE = S.DATA_FETCH_DATE ) SELECT fetch_date, category, sku, -- Unicommerce Live Flag (1 if live, 0 if not) uc_availability_flag AS unicommerce_live_skus, -- Shopify Live Flag (1 if live, 0 if not) CASE WHEN shopify_available > 0 THEN 1 ELSE 0 END AS shopify_live_skus, -- Missing Flag (1 if live in Unicommerce but OOS/missing in Shopify) CASE WHEN uc_availability_flag = 1 AND IFNULL(shopify_available, 0) <= 0 THEN 1 ELSE 0 END AS missing_skus_count, -- Inventory Quantities for deep dive uc_available_inventory AS unicommerce_available_qty, shopify_available AS shopify_available_qty FROM SKU_Comparison WHERE fetch_date = CURRENT_DATE(\"Asia/Kolkata\") ORDER BY category, sku;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            